    visited_7 = set()

    # Find all 7 pixels
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 7:
                visited_7.add((r, c))

    # Find all neighbors at distance 1 from any 7
    new_7s = set(visited_7)
    for r, c in visited_7:
        for dr, dc in [(1,0), (-1, 0), (0, 1), (0, -1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                new_7s.add((nr, nc))

    # Find all 4s (they stay as 4)
    fours = set()
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 4:
                fours.add((r, c))

    # Build output
