# Recursively collect all keys  
def get_all_keys(obj, prefix=""):
    keys = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            keys[k] = v
            keys.update(get_all_keys(v, f"{prefix}{k}.") if isinstance(v, (dict,list)) else {"non_obj": [v]})
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            keys[i] = item
            keys.update(get_all_keys(item, f"{prefix}[{i}].") if isinstance(item, (dict,list)) else {"non_list": [item]})
    return keys

